  // ══ §3 联系人 · 群 ══
  // id：K（柯大河置顶）/ g_all（全员群）/ t_<旗下的人或见过的人 id> / n_<名字>（员工、圈里的人、小柯给了联系方式的人）
  // 员工表、群成员、旗下的人都问主脚本要（按身份不同），这里不写死
  var THEME = { '柯大河': '#3d5a6c' };
  function themeOf(name) {
