  function staffList(s) {   // [[名字, 一句身份], ...]，柯大河单独置顶，不在这里重复
    try { var a = C.staff ? C.staff(s) : []; return (Array.isArray(a) ? a : []).filter(function (x) { return x && x[0] && x[0] !== K_NAME; }); } catch (e) { return []; }
  }
  function rosterOf(s) {   // [{ id, name, realName, stageName, sub, portrait, kind }]
    try { var a = C.roster ? C.roster(s) : []; return (Array.isArray(a) ? a : []).filter(function (r) { return r && r.id != null; }); } catch (e) { return []; }
  }
  function kSub(s) { try { return (C.kSub && C.kSub(s)) || 'AD · 摄影'; } catch (e) { return 'AD · 摄影'; } }
  function contacts(s) {
    s = s || st();
    var d = dd(s), out = [{ id: K_ID, name: K_NAME, sub: kSub(s), kind: 'K' }];
    staffList(s).forEach(function (x) { out.push({ id: 'n_' + x[0], name: x[0], sub: x[1] || '', kind: 'staff' }); });
    rosterOf(s).forEach(function (r) {
