      var a = d.added[id] || {};
      var r = a.kind === 'met' ? (s.met || []).find(function (x) { return x && 't_' + x.id === id; }) : null;
      out.push({ id: id, name: a.name || (r && (r.name || r.stageName || r.realName)) || id, sub: a.kind === 'met' ? '见过 · 小柯给的联系方式' : (a.sub || '小柯给的联系方式'), kind: r ? 'met' : 'free', ref: r || null });
    });
