    try { if (DD) DD.refreshInjection(); } catch (e) {}
    var k = identity();
    if (!k || OPENING.live) return;
    type = type || 'normal';
    if (type !== 'normal' && type !== 'swipe' && type !== 'regenerate') return;
    var n = lastId();
    var target = (type === 'swipe') ? n : n + 1;   // 这次要写的是第几楼
    if (target === 1) injectOpening(k);
  }

  // 【片场近况】每轮挂，深度 1，system；玩家看不见。剧情时间照纸醉金迷的 [TIME]：脚本读完就从楼层里擦掉
  var TIME_ASK = '这条回复写完，最后单独一行写剧情时间 [TIME:HH:MM|M/D]：这条回复结尾那一刻的时间，日期从上面那天往后接；故事过了夜，就写第二天的日期。';
  var NEWS_GOT = {}, NEWS_GONE = {};
  function recentLine(st, news) {
    st = st || readState();
