  }
  async function clearScene() { try { uninjectPrompts([ID_SCENE]); } catch (e) {} GOT_MEM = null; await save(function (s) { delete s.scene; }); }

  // 片场：拍摄中每轮都挂当前这一场（剧本系统第三节：片头 + 选角 + 前情 + 上一场的钩 + 状态 + 当前这一场全文）
  var SCRIPT_CACHE = {};
