    on(T.MESSAGE_RECEIVED, onMainReceived);
    on(T.MESSAGE_SENT, onUserSent);
    on(T.GENERATION_AFTER_COMMANDS, onBeforeGen);
    on(T.GENERATION_ENDED, openingSpent);
    on(T.GENERATION_STOPPED, openingSpent);
    try { if (typeof iframe_events !== 'undefined') on(iframe_events.GENERATION_ENDED, openingSpent); } catch (e) {}
    try {
      var btns = [{ name: BTN_PANEL, visible: true }, { name: BTN_RESET, visible: true }];
      if (typeof appendInexistentScriptButtons === 'function') appendInexistentScriptButtons(btns);
      else if (typeof replaceScriptButtons === 'function') replaceScriptButtons(btns);
    } catch (e) {}
    try { on(getButtonEvent(BTN_RESET), onReset); } catch (e) {}
    // 脚本按钮兜底：场记板拖丢了 / 看不见 → 点它复位并开关面板（没选身份时场记板藏着，不动它记下的位置，只开面板）
    try { on(getButtonEvent(BTN_PANEL), function () { if (identity()) { lsDel(FAB_POS); defaultFab(); } togglePanel(); }); } catch (e) {}
  }

  var cleaned = false;
  function cleanup() {
    if (cleaned) return; cleaned = true;
    applyInputLock(true);
    STOPS.forEach(function (s) { try { s(); } catch (e) {} }); STOPS = [];
    try { if (MO) MO.disconnect(); } catch (e) {} MO = null;
    if (_tick) { clearTimeout(_tick); _tick = null; }
    try { if (DD) DD.cleanup(); } catch (e) {}
    try { uninjectPrompts([ID_IDENTITY, ID_OPENING, ID_RECENT, ID_SCENE, ID_SHOOT]); } catch (e) {}
    try { VIEW.removeEventListener('resize', onResize); } catch (e) {}
    try { if (BAR_RO) BAR_RO.disconnect(); } catch (e) {} BAR_RO = null;
    [BOARD_ID, STYLE_ID, FAB_ID, PANEL_ID, PSTYLE_ID].forEach(function (id) { var el = DOC.getElementById(id); if (el) el.remove(); });
    if (VIEW[INSTANCE_KEY] === cleanup) VIEW[INSTANCE_KEY] = null;
  }
  VIEW[INSTANCE_KEY] = cleanup;
  window.addEventListener('pagehide', cleanup);

  // ═════════════════════════ 启动 ═════════════════════════
  bindEvents();
  bindObserver();
  applyIdentityInjection();
  applyScene(); applyShoot(); applyRecent();
  refresh();
  homeFab();   // 有身份：按记下的 / 默认位置摆；没身份藏着，入职那一下 fabRefresh 再摆
  try { VIEW.addEventListener('resize', onResize); } catch (e) {}
  watchBar();
  ddBadge();
  setTimeout(hintOldChat, 800);

  // 测试 / 调试钩子（无副作用）
  try {
    window.__pianchang = { version: VERSION, state: readState, identity: identity, lastId: lastId, refresh: refresh, apply: apply, reset: onReset, depts: DEPTS, opening: OPENING, ui: UI, bui: BUI,
      open: openPanel, close: closePanel, render: render, panel: PANEL, fab: FAB, core: C, save: save, cur: function () { return CUR; }, gen: GEN, endDays: endDays, nextMark: nextMark,
      startShootDir: startShootDir, startShootAct: startShootAct, shootNext: shootNext, shootCut: shootCut, shootWrap: shootWrap, doFinish: doFinish, writeScript: writeScript, kAsk: kAsk, dd: DD };
  } catch (e) {}
  console.info('[声色片场] 🎬 主脚本 v' + VERSION + ' 就位' + (identity() ? '（身份：' + identity() + '）' : '（还没选部门）'));
})();
